# CSV to JSON starter — OG Companion
# Run: python og-starter.py journeys.csv valid-journeys.json
# Read any CSV headers, reject incomplete rows, display valid rows and save JSON.
import argparse
import csv
import json
from pathlib import Path


def valid_row(row):
    # DictReader uses None for missing cells and for extra unnamed columns.
    return bool(row) and None not in row and all(
        isinstance(value, str) and bool(value.strip()) for value in row.values()
    )


def load_rows(path):
    accepted = []
    rejected = 0
    with path.open(encoding="utf-8-sig", newline="") as source:
        reader = csv.DictReader(source)
        if not reader.fieldnames:
            raise ValueError("The CSV needs a header row.")
        for row in reader:
            if valid_row(row):
                accepted.append(row)
            else:
                rejected += 1
    return accepted, rejected


def main():
    parser = argparse.ArgumentParser(description="Check CSV rows and save valid records as JSON.")
    parser.add_argument("input_csv", type=Path)
    parser.add_argument("output_json", type=Path)
    args = parser.parse_args()
    if args.input_csv.resolve() == args.output_json.resolve():
        parser.error("Choose a different output file so the CSV is kept.")
    try:
        rows, rejected = load_rows(args.input_csv)
        for row in rows:
            print(json.dumps(row, ensure_ascii=False))
        args.output_json.write_text(json.dumps(rows, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    except (OSError, ValueError, csv.Error) as error:
        parser.exit(1, f"Could not process the file: {error}\n")
    print(f"Valid rows: {len(rows)}; rejected rows: {rejected}")
    print(f"Saved to {args.output_json}")
    # Extend valid_row() with checks for your own fields, types or permitted values.
    # Add filtering or calculations after load_rows(), before displaying and saving.


if __name__ == "__main__":
    main()

