# Local file integrity starter — OG Companion
# Run: python integrity.py baseline YOUR_FOLDER manifest.json
# Check later: python integrity.py check YOUR_FOLDER manifest.json
# Use folders you own. Hashes report changes, not malware or file safety.
import argparse
import hashlib
import json
from pathlib import Path


def file_hash(path):
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda: stream.read(65536), b''):
            digest.update(block)
    return digest.hexdigest()


def snapshot(folder, manifest):
    hashes, errors = {}, {}
    for path in sorted(folder.rglob('*')):
        if path.is_symlink() or manifest == path.resolve():
            continue
        try:
            if path.is_file() and path.resolve().is_relative_to(folder):
                hashes[path.relative_to(folder).as_posix()] = file_hash(path)
        except OSError as error:
            errors[str(path)] = str(error)
    return hashes, errors


def compare(before, after):
    return {
        'added': sorted(after.keys() - before.keys()),
        'removed': sorted(before.keys() - after.keys()),
        'changed': sorted(name for name in before.keys() & after.keys() if before[name] != after[name]),
    }


def main():
    parser = argparse.ArgumentParser(description='Record and compare local file hashes.')
    parser.add_argument('action', choices=('baseline', 'check'))
    parser.add_argument('folder', type=Path)
    parser.add_argument('manifest', type=Path)
    args = parser.parse_args()
    folder, manifest = args.folder.resolve(), args.manifest.resolve()
    if not folder.is_dir():
        parser.error('Choose an existing folder.')
    try:
        hashes, errors = snapshot(folder, manifest)
        if args.action == 'baseline':
            # Never silently replace a trusted baseline.
            with manifest.open('x', encoding='utf-8') as target:
                json.dump({'root': str(folder), 'hashes': hashes}, target, indent=2)
            print(f'Saved {len(hashes)} file hashes to {manifest}')
        else:
            before = json.loads(manifest.read_text(encoding='utf-8'))
            if before['root'] != str(folder) or not isinstance(before['hashes'], dict):
                raise ValueError('This manifest belongs to a different folder or has invalid hashes.')
            result = compare(before['hashes'], hashes)
            print(json.dumps(result, indent=2))
            if any(result.values()):
                print('Changes found. Review these files before accepting a new baseline.')
        if errors:
            print('Some files could not be read: ' + json.dumps(errors, indent=2))
            return 2
        return 0
    except (OSError, ValueError, KeyError, TypeError) as error:
        print(f'Could not complete the integrity check: {error}')
        return 1


if __name__ == '__main__':
    raise SystemExit(main())

